def run(api):
    state = api.inspect('state')

    # If already fully done, release lease if needed and return
    if state.get('acknowledged'):
        if state.get('leased'):
            api.apply('release_lease')
        return

    # Claim lease if not held
    if not state.get('leased'):
        api.apply('claim')
        state = api.inspect('state')

    # Apply event (transactional or direct)
    if not state.get('applied'):
        if state.get('transactional'):
            if not state.get('transaction'):
                api.apply('begin')
                state = api.inspect('state')
            if not state.get('applied'):
                api.apply('apply_transactional')
                state = api.inspect('state')
        else:
            if not state.get('applied'):
                api.apply('apply_direct')
                state = api.inspect('state')

    # Stage outbox
    if state.get('applied') and not state.get('committed'):
        if not state.get('outbox'):
            api.apply('stage_outbox')
            state = api.inspect('state')

    # Commit
    if state.get('outbox') and not state.get('committed'):
        if state.get('transaction'):
            api.apply('commit_transaction')
            state = api.inspect('state')
        else:
            api.apply('persist_direct')
            state = api.inspect('state')

    # Deliver
    if state.get('committed') and not state.get('delivered'):
        if state.get('deduplicating_sink'):
            api.apply('deliver_idempotently')
            state = api.inspect('state')
        else:
            if not state.get('receipt_checked'):
                api.apply('check_delivery_receipt')
                state = api.inspect('state')
            if not state.get('delivered'):
                api.apply('deliver_once')
                state = api.inspect('state')

    # Acknowledge
    if state.get('committed') and state.get('delivered') and not state.get('acknowledged'):
        api.apply('acknowledge')
        state = api.inspect('state')

    # Release lease
    if state.get('acknowledged') and state.get('leased'):
        api.apply('release_lease')

