def run(api):
    state = api.inspect('state')

    if not state['leased']:
        state = api.apply('claim')

    if state['transactional'] and not state['applied'] and not state['transaction']:
        state = api.apply('begin')
        state = api.apply('apply_transactional')
        state = api.apply('stage_outbox')
        state = api.apply('commit_transaction')

    if not state['transactional'] and not state['applied']:
        state = api.apply('apply_direct')
        state = api.apply('stage_outbox')
        state = api.apply('persist_direct')

    if state['applied'] and not state['outbox']:
        state = api.apply('stage_outbox')

    if state['outbox'] and not state['committed']:
        if state['transactional'] and state['transaction']:
            state = api.apply('commit_transaction')
        elif not state['transactional']:
            state = api.apply('persist_direct')

    if state['committed'] and state['deduplicating_sink'] and not state['delivered']:
        state = api.apply('deliver_idempotently')

    if state['committed'] and not state['delivered']:
        if not state['receipt_checked']:
            state = api.apply('check_delivery_receipt')
        if not state['delivered']:
            state = api.apply('deliver_once')

    if state['leased'] and state['committed'] and state['delivered'] and not state['acknowledged']:
        state = api.apply('acknowledge')

    if state['leased'] and state['acknowledged']:
        state = api.apply('release_lease')

    return state

